// Sinh bởi `node scripts/templates.mjs` từ lib/canvas/doc.ts, templates/README.md và templates/taste.md — đừng sửa tay.
export const DOC_SPEC = "/**\n * Trang của quán là một tài liệu canvas (đợt ②, kịch bản mục 8–9; Tài 05/10: \"dựng lại template từ PNG/PDF\", \"canvas theo\n * khổ điện thoại, co theo bề ngang màn hình\", \"trang chia khúc xếp dọc\").\n *\n * - Một trang = các **khúc** (section) xếp dọc. Mỗi khúc là một tấm khổ điện thoại rộng `ARTBOARD` đơn vị, cao `h` đơn vị;\n *   trên máy thật một đơn vị = bề ngang cột trang / 390 (cột rộng tối đa 480px), nên cả khúc co giãn theo bề ngang.\n * - Phần tử đặt tự do như Canva (x, y, w, h, xoay). Riêng **chồng** (`stack`) tự xếp con theo chiều dọc — nút mạng xã hội\n *   thêm/bớt không phải kéo tay, và hiệu ứng \"hiện lần lượt, đẩy phần dưới xuống\" (mẫu Dynamic movement).\n * - Mọi con số là đơn vị thiết kế; mọi chiều cao đều khai báo, nên vị trí của mọi phần tử tính được trên máy chủ\n *   (layout.ts) — đó là cách luật Google \"nút trong màn hình đầu\" được kiểm khi phát hành, không nhờ may mắn.\n * - Chữ có tiếng Việt và (tuỳ) tiếng Anh; thiếu tiếng Anh thì hiện tiếng Việt (luật 0.3 của kịch bản).\n *\n * Không có CSS hay HTML tự do ở đâu cả: màu, phông, biểu tượng, tranh, kiểu nút đều chọn từ danh sách dưới đây\n * (validate.ts), nên một tài liệu không bao giờ chở được mã hay kiểu lạ lên trang khách.\n */\nimport stickerData from './stickers.json' with { type: 'json' };\nimport brushData from './brushes.json' with { type: 'json' };\n\nexport const ARTBOARD = 390;\n/** The Google button's bottom edge must sit above this line in the first section: the first screen of an iPhone SE in Safari. */\nexport const FIRST_SCREEN = 560;\nexport const MAX_SECTIONS = 8;\nexport const MAX_ELEMENTS = 90;\nexport const MAX_SECTION_H = 2400;\n\nexport type Words = { vi: string; en?: string };\nexport type Color = string;\nexport type Gradient = { kind: 'linear'; angle: number; stops: [Color, number][] } | { kind: 'radial'; x: number; y: number; stops: [Color, number][] };\nexport type Fill = Color | Gradient;\nexport type Shadow = { x: number; y: number; blur: number; color: Color };\nexport type Edge = { w: number; color: Fill };\nexport type Glass = { blur: number; tint: Color };\n\n/** Typefaces the page may use, each with full Vietnamese (components/canvas/fonts.ts). */\n/** `rieng-chinh`, `rieng-dac-biet`: the shop's own fonts (doc.fonts), each falling back to a built-in face until it loads or if it is missing. */\nexport const FONTS = ['sans', 'display', 'serif', 'script', 'hand', 'rounded', 'slab', 'brush', 'geo', 'elegant', 'rieng-chinh', 'rieng-dac-biet'] as const;\nexport type FontKey = typeof FONTS[number];\n\n/** Built-in icons: brand marks drawn simply, and line glyphs (components/canvas/icons.tsx). */\nexport const ICONS = ['instagram', 'tiktok', 'zalo', 'facebook', 'youtube', 'globe', 'link', 'wifi', 'phone', 'mail', 'maps', 'google', 'pin', 'hand',\n  'cursor', 'tooth', 'sparkle', 'heart', 'plus', 'camera', 'calendar', 'shampoo', 'conditioner', 'jar', 'capsule', 'car', 'scissors', 'pole', 'cup',\n  'flag', 'polish', 'bowl', 'smile', 'clinic', 'star', 'music', 'gift', 'menu', 'bed', 'key',\n  // Biến thể dấu thương hiệu (Tài 07/10): màu thật · nét (`-net`, theo màu chữ) · đặc · tròn/vuông — để mỗi trang lấy cái hợp.\n  'zalo-oa', 'zalo-net', 'facebook-net', 'youtube-net', 'maps-giay', 'maps-mau', 'maps-net', 'google-net', 'google-tron', 'instagram-net', 'instagram-dac', 'tiktok-net', 'tiktok-vuong', 'web', 'web-tro'] as const;\n/** The marks the Google button may wear: Google's G or a Maps pin, in any of their variants. */\nexport const GOOGLE_MARKS = ['google', 'google-net', 'google-tron', 'maps', 'maps-mau', 'maps-net', 'maps-giay'] as const;\nexport type IconKey = typeof ICONS[number];\n\n/** Built-in illustrations, drawn as vector art (components/canvas/art.tsx): an image source written `art:<key>`. */\nexport const ARTS = ['barber', 'car', 'space', 'drinks', 'smile', 'arches', 'dental', 'latte', 'hair', 'prism', 'party', 'racing', 'nails', 'pho', 'photo'] as const;\nexport type ArtKey = typeof ARTS[number];\n\n/**\n * Vector shapes (components/canvas/shapes.tsx); the lights (Tài 07/10: \"ánh sáng làm nên cảm giác dễ chịu\"): `cau-vong` a thin sharp\n * ribbon of spectrum, `cau-vong-xoan` the same ribbon turning over, `vet-sang` a thin streak of light, `hat-bay` specks of light drifting up (uiverse.io vinh_8995/tame-lionfish-65, MIT) —\n * with `blend: \"screen\"`, and\n * `blur` when out of focus; warm light is `glow` in the shop's colour; then the powder\n * brushes (brushes.json, components/canvas/powder.tsx — nền kiểu Sentry: only the brush's numbers are kept, the colour is the\n * shop's); then the sticker library (stickers.json: sao, tim, mặt cười, dấu vẽ tay), each drawn in the element's colour, so one\n * sticker serves every shop, turned (`r`) and roughened (`grain`).\n */\nexport const STICKERS = stickerData as Record<string, { name: string; group: string; vb?: string; paths: StickerPath[] }>;\nexport type StickerPath = { d: string; fill?: boolean; stroke?: number; evenodd?: boolean; color?: string; opacity?: number };\nexport type Brush = { name: string; about: string; flakes: number; size: [number, number]; spread: number; clumps: number; clumpSpread: number; haze: number;\n  stretch: number; alpha: [number, number]; stray: number };\nexport const BRUSHES = brushData as unknown as Record<string, Brush>;\n/** `may-troi`: clouds drifting in three layers, far ones slower (the layered drift of uiverse.io jaykdoe/tasty-dragon-12, MIT, made\n * into clouds — Tài 07/10: \"mây khó kiếm vì Canva không tải về được\"); colours from the fill's stops. `sao-troi`: that pen's starfield. */\nexport const LIGHTS = ['cau-vong', 'cau-vong-xoan', 'vet-sang', 'hat-bay', 've', 'may-troi', 'sao-troi'] as const;\nexport const SHAPES = ['rect', 'circle', 'line', 'burst', 'sparkle', 'plus', 'heart', 'arrow', 'ribbon', 'flare', 'pin-line', 'wave', 'dots', 'checker', 'squiggle', 'glow',\n  ...LIGHTS, ...Object.keys(brushData) as (keyof typeof brushData)[], ...Object.keys(stickerData) as (keyof typeof stickerData)[]] as const;\nexport const BLENDS = ['screen', 'soft-light', 'overlay', 'multiply', 'color-dodge'] as const;\nexport type ShapeKey = typeof SHAPES[number];\n\nexport const MOTIONS_IN = ['fade', 'rise', 'drop', 'pop', 'left', 'right', 'zoom', 'blur'] as const;\n/** `xu`: turns over once like a coin, then rests (uiverse.io JohnnyCSilva/black-rabbit-68, MIT — docs/nguon-hieu-ung.md). */\nexport const MOTIONS_LOOP = ['float', 'sway', 'pulse', 'twinkle', 'spin', 'shine', 'bob', 'glow', 'xu'] as const;\nexport type Motion = { in?: typeof MOTIONS_IN[number]; at?: number; loop?: typeof MOTIONS_LOOP[number] };\n\n/** `row`: a list row — icon, words on the left, an arrow on the right (mẫu Card Stack, Tài 06/10). */\n/** `glitch`: a white pill with TikTok's two offset edges; `card`: a nearly square white card with a coloured edge (Zalo OA). */\nexport const BUTTON_LOOKS = ['pill', 'ring', 'outline', 'soft', 'gradient', 'tail', 'link', 'box', 'tag', 'note', 'glow', 'text', 'row', 'glitch', 'card'] as const;\nexport type ButtonLook = typeof BUTTON_LOOKS[number];\nexport const GOOGLE_LOOKS = ['maps', 'g', 'ring', 'glass'] as const;\nexport type GoogleLook = typeof GOOGLE_LOOKS[number];\n\n/**\n * Chỗ của quán (Tài 06/10: \"mọi thứ như link, chữ trên hitbox phải đồng bộ với shop\"): an element marked with a slot shows\n * the shop's own data, filled in where the page is shown (slots.ts), as the Google button always takes the shop's own link.\n * What the template wrote there is a sample; a shop without that piece of data does not show the element at all.\n *   name, initial      the shop's name, its first letter (text)\n *   link slots         where a button, icon, picture, shape or text leads (lib/shop/profile.ts says what each takes)\n *   handle             \"@name\" (text, or a button that leads to the shop's first social page)\n *   hours, address     a line of text\n *   wifi               the shop's network behind a wifi button\n */\nexport const LINK_SLOTS = ['zalo', 'facebook', 'instagram', 'tiktok', 'youtube', 'website', 'menu', 'booking', 'phone', 'maps', 'email'] as const;\nexport type LinkSlot = typeof LINK_SLOTS[number];\nexport const SLOTS = ['name', 'initial', ...LINK_SLOTS, 'handle', 'hours', 'address', 'wifi'] as const;\nexport type SlotKey = typeof SLOTS[number];\n\ntype Box = { id: string; name?: string; x: number; y: number; w: number; h: number; r?: number; o?: number; hide?: boolean; lock?: boolean; motion?: Motion;\n  slot?: SlotKey };\nexport type TextEl = Box & { t: 'text'; words: Words; font: FontKey; size: number; weight?: number; color: Color;\n  /** Letters coloured in turn (the round button's thank-you line in Google's colours). */\n  colors?: Color[];\n  align?: 'left' | 'center' | 'right'; spacing?: number; line?: number; italic?: boolean; caps?: boolean; shadow?: Shadow;\n  stroke?: { w: number; color: Color }; underline?: boolean;\n  /** Set on an arc: the circle's radius in units, positive bends like a smile turned over (text over a cup), negative like a smile. */\n  arc?: number; link?: string;\n  /** Letters filled with a gradient instead of one colour (a ticket's title, uiverse.io zeeshan_2112/shy-rattlesnake-3). */\n  paint?: Fill;\n  /** The words inside a filled circle: a shop's initial as its avatar (mẫu Party). */\n  disc?: { fill: Fill; edge?: Edge } };\nexport type ImageEl = Box & { t: 'image'; src: string; fit?: 'cover' | 'contain'; focus?: [number, number];\n  mask?: 'none' | 'circle' | 'clover' | 'arch' | 'blob'; radius?: number; edge?: Edge; shadow?: Shadow; gray?: boolean;\n  frame?: 'polaroid' | 'gilded'; caption?: Words; link?: string;\n  /** More of the shop's photos: the picture turns over now and then and shows the next one (Tài 07/10, ảnh polaroid 4RAU). */\n  flip?: string[] };\n/**\n * `blur`: the shape itself softened (a shadow cast on the floor under a card, Tài 06/10), in units. `grain`: drawn as with a crayon —\n * the edge wavers and the colour has small gaps (dấu cộng, tim vẽ tay kiểu Sentry, Tài 07/10).\n */\nexport type ShapeEl = Box & { t: 'shape'; shape: ShapeKey; fill?: Fill; edge?: Edge; radius?: number; glass?: Glass; shadow?: Shadow; link?: string; blur?: number; grain?: boolean;\n  /** How it mixes with what lies under it: light is `screen` (it only brightens), shade is `multiply`. */\n  blend?: typeof BLENDS[number] };\nexport type IconEl = Box & { t: 'icon'; icon: IconKey; color?: Color; link?: string };\nexport type ButtonEl = Box & { t: 'button'; look: ButtonLook; label: Words; link?: string;\n  /** A wifi button shows the shop's network instead of leaving the page. */\n  wifi?: { name: string; pass?: string };\n  icon?: IconKey; tag?: Words; bg?: Fill; fg?: Color; edge?: Edge; font?: FontKey; size?: number; shadow?: Shadow; weight?: number; spacing?: number };\n/**\n * The Google review button. Its words and its link are the platform's (the shop's Place ID); only its look is the template's.\n * `shadow`: how far it stands off the page (a knob in Bàn dựng, Tài 06/10: \"nổi bóng để nổi bật khỏi nền\"): none · soft · lift (a\n * deep, layered shadow) · hard (a solid offset block in `shade`).\n */\nexport const GOOGLE_SHADOWS = ['none', 'soft', 'lift', 'hard', 'halo'] as const;\nexport type GoogleEl = Box & { t: 'google'; look: GoogleLook; bg?: Fill; fg?: Color; shadow?: typeof GOOGLE_SHADOWS[number]; shade?: Color; bar?: Color; ring?: Color;\n  /** Corner rounding in units (a pill when absent), an arrow at the right end as a list row has, and the words' size in units. */\n  radius?: number; arrow?: boolean; size?: number;\n  /** A double stripe of light sweeping across now and then, in this colour (uiverse.io Ashon-G/rotten-frog-52, MIT). */\n  shine?: Color;\n  /** Which mark it wears, where the look shows one (`maps`, `g`, `glass`); each look has its own when absent. */\n  mark?: typeof GOOGLE_MARKS[number] };\n/**\n * The paper plane that opens the private-feedback card: the original guest page's, kept as it was (Tài 05/10), floating at the\n * screen's lower left wherever the guest has scrolled (components/guest/plane.css). Its place in the document only says the\n * page has one; the page chooses its glyph and two colours, as the page's settings always could.\n */\nexport type FeedbackEl = Box & { t: 'feedback'; icon: 'plane' | 'chat' | 'mail'; color: Color; edge: Color;\n  /** The screen's corner it floats in, chosen where it covers no picture or button of the page (Tài 06/10). */\n  side?: 'left' | 'right' };\nexport type LangEl = Box & { t: 'lang'; look: 'select' | 'chip'; color: Color; bg?: Fill; label?: boolean };\nexport type LegalEl = Box & { t: 'legal'; color: Color; size?: number };\nexport type Leaf = TextEl | ImageEl | ShapeEl | IconEl | ButtonEl | GoogleEl | LangEl | LegalEl;\n/** Omit, applied to each member of a union on its own (the built-in Omit flattens a union into its common keys). */\ntype Without<T, K extends PropertyKey> = T extends unknown ? Omit<T, K> : never;\n/** Side by side inside a row a child has its own width; its place is the row's to decide. */\nexport type RowKid = Without<Leaf, 'x' | 'y' | 'w'> & { w: number };\n/** Laid out side by side inside a stack: three service buttons in a row. */\nexport type RowEl = { id: string; t: 'row'; h: number; w?: number; gap: number; kids: RowKid[]; hide?: boolean };\n/** Inside a stack a child's x and y are the stack's to decide; its height is still its own (layout stays computable). */\nexport type Kid = (Without<Leaf, 'x' | 'y' | 'w'> & { w?: number }) | RowEl;\n/** `top`: the panel starts this many units below the container's top, so a first child (an avatar) can sit half outside it. */\nexport type Panel = { fill?: Fill; glass?: Glass; radius?: number; edge?: Edge; shadow?: Shadow; top?: number };\nexport type StackEl = Box & { t: 'stack'; kids: Kid[]; gap: number; pad?: number; align?: 'start' | 'center' | 'end' | 'stretch'; panel?: Panel;\n  /** Milliseconds between children appearing one after another; each pushes what follows down (mẫu Dynamic movement). */\n  reveal?: number };\n/** One card behind the front card of a deck (mẫu Interactive card): a tap pulls it out, a second tap follows its link. */\nexport type DeckCard = { icon: IconKey; label: Words; link: string; fill: Fill; fg?: Color; slot?: LinkSlot; hide?: boolean };\nexport const DECK_LOOKS = ['party', 'racing', 'nails', 'pho'] as const;\nexport type DeckEl = Box & { t: 'deck'; look: typeof DECK_LOOKS[number]; front: { kids: Kid[]; gap: number; pad?: number; panel?: Panel; tilt?: number }; cards: DeckCard[] };\n/**\n * Các nút của quán, tự sinh (Tài 07/10: \"điền bao nhiêu link thì render bấy nhiêu nút, chỗ nào chưa điền thì không render\"): one\n * button per link the shop has, in `order`, nothing for a link it lacks, and the whole group gone when it has none. The page never\n * lists sample links here: `items` is filled from the shop's details each time the page is shown (slots.ts), never stored.\n *   look   icons (a row of marks) · pills (mark + name) · rows (list rows with an arrow)\n *   style  mau (brand colours) · net (thin line in `color`) · dac (solid in `color`)\n */\nexport const LINKS_LOOKS = ['icons', 'pills', 'rows'] as const;\nexport type LinksEl = Box & { t: 'links'; look: typeof LINKS_LOOKS[number]; style?: 'mau' | 'net' | 'dac'; color?: Color; bg?: Fill; gap?: number; size?: number;\n  order?: LinkSlot[]; items?: { slot: LinkSlot; url: string; label?: string }[] };\nexport type El = Leaf | FeedbackEl | StackEl | DeckEl | LinksEl;\n\n/**\n * `extend: 'blur'`: the picture keeps its own shape at the top of the section, full width, and the rest of the section continues in a\n * blurred copy of it (Tài 06/10: \"nếu ảnh ngắn thì render blur out ra\"), so a section may grow past the picture.\n */\nexport type Background = { fill?: Fill; src?: string; fit?: 'cover' | 'contain'; focus?: [number, number]; gray?: boolean; blur?: number; dim?: number; extend?: 'blur' };\nexport type Section = { id: string; name?: string; h: number; bg?: Background; els: El[] };\n/** A vertical band behind every section (mẫu hair styling: a brown strip as a second background). */\nexport type Band = { x: number; w: number; fill: Fill; blur?: number };\nexport type PageDoc = {\n  v: 1;\n  /** The shop's own font files (uploads), for the `rieng-chinh` and `rieng-dac-biet` faces. */\n  fonts?: { chinh?: string; dacBiet?: string };\n  /** Background sound (an upload): off until the guest taps the speaker — browsers never let a page start sound by itself. */\n  sound?: { src: string; volume?: number };\n  /** A background that stays still behind the whole page while it scrolls. */\n  backdrop?: Background;\n  band?: Band;\n  sections: Section[];\n  fx?: {\n    /** Milliseconds before a \"scroll to see more\" arrow appears, if the guest has not scrolled (mẫu Illustrate). */\n    hint?: number;\n    /** The thank-you card before Google opens (components/effects/thanks.tsx), counting this many seconds (1–4). */\n    thanks?: number;\n  };\n};\n\nexport const pick = (words: Words, lang: 'vi' | 'en') => (lang === 'en' && words.en?.trim() ? words.en : words.vi);\n";
export const TEMPLATE_RULES = "# Template\n\nMỗi template của trang khách là **một thư mục ở đây, một tệp `template.json`** (đợt ②, 05/10/2026: template canvas, dựng\nlại từ ảnh Tài gửi). Không chỗ nào khác trong mã liệt kê template. Làm template không cần đụng TypeScript.\n\nTrước khi làm, đọc `rieng/kich-ban.md` mục 8–9 (chỉ có trên máy Tài) và `docs/google-policy.md`. Luật Google thắng mọi thứ.\n\n## `template.json`\n\n| Trường | Ý nghĩa |\n|---|---|\n| `key` | Trùng tên thư mục. Chữ thường, số, gạch nối. **Không bao giờ đổi**: trang tạo từ template ghi lại nó. Không mang tên thương hiệu. |\n| `number` | Số thứ tự trong Library. |\n| `name` | Tên ngắn chủ quán thấy. |\n| `groups` | Nhóm trong Library (kịch bản mục 8): \"Only Poster\", \"Only Background\", \"Interactive cards\", \"Simple\", \"Không gian thực\", \"Tối giản\", \"Trong suốt\", \"Thuỷ tinh\"… hoặc nhóm mới. |\n| `about` | Một câu: template này chạy thế nào. |\n| `doc` | Tài liệu trang — đúng kiểu `PageDoc` trong `lib/canvas/doc.ts`: các **khúc** xếp dọc, mỗi khúc khổ điện thoại rộng 390 đơn vị; phần tử đặt tự do (x, y, w, h, xoay), riêng `stack` tự xếp con theo chiều dọc. |\n\nTrang mới tạo từ template là **bản sao** của `doc`: sửa trang không đổi template, sửa template không đổi trang đã có.\n\n## Chỗ của quán (`slot`) — bắt buộc cho mọi thứ thuộc về quán\n\nMẫu chỉ là bố cục; tên, link, @tên, giờ mở cửa, wifi là **của từng quán** (Tài 06/10). Phần tử nào chứa thứ của quán thì ghi\n`\"slot\": \"<khoá>\"`; lúc trang hiện ra, hệ thống điền **thông tin quán** vào đó (`lib/canvas/slots.ts`), quán chưa có thì\n**phần tử ẩn hẳn**. Chữ và link mẫu trong template chỉ để xem thử; trang lưu giữ nguyên chúng, không bao giờ ghi đè.\n\n| `slot` | Đặt trên | Nhận |\n|---|---|---|\n| `name` · `initial` | chữ | tên quán (giữ chữ hoa nếu mẫu viết hoa, tự thu nhỏ cho vừa khung) · chữ cái đầu |\n| `zalo` `facebook` `instagram` `tiktok` `youtube` `website` `menu` `booking` `phone` `maps` | nút, biểu tượng, ảnh, hình, chữ có link | link của quán; nhãn nút là địa chỉ mẫu (vd `tenquan.vn`) thì thành tên miền của quán |\n| `handle` | chữ, hoặc nút có link | `@tên` của quán; nút dẫn tới trang mạng xã hội đầu tiên quán có |\n| `hours` · `address` | chữ | giờ mở cửa · địa chỉ |\n| `wifi` | nút wifi | tên và mật khẩu wifi của quán |\n\nThẻ trong bộ bài (mẫu Party) cũng nhận `slot` link. **Mọi link mẫu** (trang chủ trần của Zalo, Facebook, TikTok…, hoặc link về\nQuite Sensational) phải nằm trong một `slot`: lõi phát hành từ chối trang còn link mẫu ở chỗ khách bấm được, và test\n`tests/contracts/templates.spec.ts` kiểm điều đó cho từng mẫu (quán trống thông tin: không còn link mẫu; quán đủ thông tin: mọi\nchỗ đều được điền). Chữ chủ đề của mẫu (vd \"HAIR SALON\", danh sách dịch vụ nha khoa) không phải chỗ của quán; admin sửa thẳng\nkhi quán muốn khác.\n\n## Núm (`knobs`) — mọi mẫu mới\n\nNhững gì khách hay muốn đổi, để Bàn dựng đổi mà không vẽ lại (kịch bản 9b, `lib/canvas/knobs.ts`, sổ tay\n`docs/khach-chinh-mau.md`):\n\n| Trường | Ý nghĩa |\n|---|---|\n| `palettes` | 3–5 bảng màu có tên, cùng số màu (`#rrggbb`). Bảng đầu là màu tài liệu đang dùng; đổi bảng là thay từng màu theo vị trí ở mọi chỗ (giữ độ trong `#rrggbbaa`). Vì vậy mọi màu đổi theo bảng phải viết đúng bằng một màu của bảng đầu; màu không đổi (trắng, máy bay giấy) thì dùng màu ngoài bảng. |\n| `photos` | `[{ id, name }]`: các phần tử ảnh nhận ảnh của quán. |\n| `texts` | `[{ id, name }]`: chữ của quán ngoài tên (câu chào). |\n\nKhách xem mọi bảng màu ở `/templates/<khoá>/mau?ten=<Tên quán>`, một mẫu với bảng thứ n ở `/templates/<khoá>?mau=n`.\n\n## Luật mà mọi template phải qua\n\n- **Nút Google** (`\"t\": \"google\"`): nhiều nhất một; nằm trọn trong khúc đầu, **trên vạch 560 đơn vị** (màn hình đầu của\n  iPhone SE); không ô góp ý nào đứng trên nó. Chữ và link của nút là của nền tảng (link đánh giá của quán từ Place ID):\n  template chỉ chọn kiểu (`look`), màu, bóng. Nút luôn nổi trên cùng, không gì che được.\n- **Không chữ nào đổi quà lấy đánh giá**, không nhắc sao, không gợi nội dung đánh giá (bẫy chữ trong `lib/publishing/policy.ts`\n  đọc mọi chữ, cả tiếng Anh).\n- **Ảnh**: `art:<khoá>` (tranh vector vẽ sẵn, `components/canvas/art.tsx`), `/tpl/<tệp>` (tệp đi kèm app), hoặc ảnh quán\n  tải lên (phải qua duyệt mới phát hành được). Không ảnh kho có bản quyền, không logo thật.\n- Màu, phông, biểu tượng, hình, kiểu nút, hiệu ứng chỉ chọn từ danh sách trong `lib/canvas/doc.ts`; không CSS, không HTML.\n\n## Sau mỗi lần thêm hay sửa\n\n```bash\nnode scripts/templates.mjs\nnode node_modules/@playwright/test/cli.js test --config=playwright.contracts.config.ts tests/contracts/templates.spec.ts\n```\n\nLệnh đầu sinh lại `lib/canvas/templates.generated.ts` (đừng sửa tay). Lệnh sau kiểm từng tài liệu và luật Google. Xem thử\ntrên máy: `node scripts/local.mjs` rồi mở `http://127.0.0.1:3321/templates/<khoá>`.\n";
export const TASTE = "# Gu của Tài (taste.md)\n\nGốc của mọi trang dựng sau này (Tài 06/10): **một lần là ưng**, với mọi loại ảnh chụp Tài gửi. Claude Code và \"Nhờ Claude\"\n(Bàn dựng, Claude API) đọc tệp này trước khi dựng. Mỗi lần Tài sửa là **một luật mới ở đây**, kèm lý do; luật nào sai thì\nsửa hoặc xoá, không chồng. Số đo theo đơn vị trang (khổ 390).\n\n## Cách dựng từ ảnh chụp\n\n1. **Ảnh chụp là bản thiết kế, không phải gợi ý.** Đo vị trí, cỡ, màu từ ảnh (bỏ khung điện thoại, quy về 390 đơn vị), không ước\n   chừng. Màu lấy mẫu điểm ảnh; ảnh nền tìm đúng khung cắt và độ phóng bằng cách so điểm ảnh, không đoán.\n2. **Không thêm gì ngoài ảnh chụp** (chữ, dấu @, nút, khung). Chỉ thêm khi Tài dặn trong lời nhắn, và lấy đúng thông tin quán\n   Tài đã điền trong tool.\n3. **Tự so trước khi gửi.** Dựng → chụp bằng Chrome ở đúng khổ ảnh gốc → đặt cạnh nhau và chồng lên nhau → sửa chỗ lệch →\n   lặp. Chỉ gửi Tài khi chồng lên nhau gần như trùng.\n4. **Tệp thừa khách gửi** (ảnh không có trong bản thiết kế, ảnh xấu): không dùng, báo lại một dòng.\n5. **Thứ không có sẵn** (font Tài chưa gửi, hình lạ): vẽ lại bằng vector theo ảnh, nét phải **đầy đặn như bản gốc**, không\n   mảnh hơn; so ở độ phóng 8 lần. Font thật luôn thắng hàng vẽ tay: hỏi Tài file font trước khi vẽ.\n\n## Luôn có trên mọi trang\n\n- **Chọn ngôn ngữ ở trên cùng** (góc trên, không đè hình chính).\n- **Dòng pháp lý nằm trong trang**, bố trí như một phần của thiết kế (cuối khúc A, màu hợp nền), không để nền tảng tự thêm ở\n  ngoài rìa. Khúc A dài ra để chứa nó; ảnh nền ngắn hơn khúc thì nối bằng bản mờ của chính ảnh đó (`extend: \"blur\"`), cùng màu\n  nền lấy từ đáy ảnh.\n- **Máy bay giấy** luôn có; chọn góc màn hình (`side`) không đè hình, nút, và chừa chỗ cho khối sự kiện sau này ở khúc A.\n- **Hiệu ứng vào cho mọi phần tử**, lần lượt từ trên xuống (khung → trang trí → chữ lớn → nút Google → chữ nhỏ → link), cách nhau\n  ~100 ms; vuốt lên xuống là phần tử chạy lại hiệu ứng khi quay vào màn hình.\n- **Nút Google nổi khỏi nền** (`shadow: \"lift\"` mặc định trên nền ảnh; `hard` + `shade` khi thiết kế có bóng khối màu). Cỡ nút\n  theo ảnh chụp.\n\n## Chất \"premium\"\n\n- **Bóng đổ phải có hình**: bóng sàn dưới thẻ là một dải đậm ở giữa, mép trên sắc, nhạt dần xuống dưới và ra hai bên — không\n  phải một thanh xám đều màu.\n- **Viền thẻ kính**: gradient nhẹ (trắng → trong → xanh nhạt → trắng, 135°), không viền trắng phẳng.\n- **Kính mờ** phải mờ thật phía sau (blur ~16); kiểm bằng ảnh chụp, vì một lỗi nhỏ là kính thành trong suốt.\n- **Ruy băng, sticker, icon trang trí**: dùng tệp trong kho (`public/tpl/`) để giống hệt và đỡ công vẽ lại.\n- **Kho chi tiết nhỏ** (`lib/canvas/stickers.json`, xem ở `/gov/kho`): sao lấp lánh, tim, mặt cười, dấu vẽ tay — mỗi cái đổi màu theo\n  quán, xoay nhẹ (`r` ±8–15°) để không cái nào giống cái nào, `grain` cho chất sáp màu. Rải thưa: 3–5 cái mỗi màn hình, to nhỏ khác\n  nhau, một màu nhấn và một màu phụ. Thiếu kiểu nào thì vẽ thêm vào kho, đừng vẽ riêng trong trang.\n- **Nền bột phấn = cọ** (kiểu Sentry, vẽ như app trên iPad, không như code): kho chỉ lưu **thông số cọ** (`lib/canvas/brushes.json`:\n  độ dày hạt, cỡ hạt, độ toả, độ cụm, lớp mờ); **màu luôn suy từ quán**. Chấm 3–5 lần to nhỏ chồng nhau như phấn trang điểm\n  (`bot-xit` phủ rộng → `bot-may` → `bot-vet` → `bot-cham`, `bot-hat` rắc trên cùng), `o` 0,4–0,75, đặt lệch ra ngoài mép màn hình.\n  `bot-hat` màu kem, `blend: \"screen\"`, `o` ~0,15 phủ cả trang là hạt phim cho chất retro.\n- **Ánh sáng làm trang dễ chịu, thân thuộc** — trang nào cũng có nguồn sáng:\n  - **Đèn ấm**: `glow` màu ấm của quán, `blend: \"screen\"`, đặt ở một góc (thường trên trái) và sau vật chính (biển hiệu, logo).\n  - **Cầu vồng** (`cau-vong`, `cau-vong-xoan`): dải phổ **mảnh, mép sắc**, ít thôi (1–2 dải), quanh vật chính; dải ở xa thì `blur`\n    nhẹ cho như lệch tiêu cự. Mắt không nhận ra ngay, chỉ thấy \"premium\" và tự nhiên.\n  - **Vệt sáng** (`vet-sang`) mảnh, chéo nhẹ. Không vẽ chấm halftone làm ánh sáng — đó là hoạ tiết riêng, chỉ dùng khi ảnh mẫu có.\n\n## Hiệu ứng động\n\n- Nguồn tìm hiệu ứng: **uiverse.io** (MIT), cách tìm và luật lấy ở `docs/nguon-hieu-ung.md`. Chỉ hiệu ứng tự chạy / chạm được.\n- Mỗi trang: nút Google có `shine` (vệt sáng quét thưa, màu nhạt của quán), logo tròn có thể `xu`, `hat-bay` nhẹ quanh thẻ chính.\n  Thưa và chậm — hiệu ứng gây chú ý, không gây rối.\n- Đồng xu (`xu`): mặt sau **để trống** (đĩa trơn), không lộ chữ ngược (Tài 07/10, \"rất thích\").\n- Quán có nhiều ảnh khách/không gian: dùng **ảnh lật** (`image.flip`, 3–6 ảnh) trong khung polaroid — mỗi ~4,6 giây lật mép, ảnh sau\n  thế chỗ, vệt sáng lướt qua; sau lưng đặt **đèn ấm thở** (`glow` + `loop: \"pulse\"`, `blend: \"screen\"`), một dải cầu vồng nhỏ trôi nhẹ\n  và một sao lấp lánh, cho khu vực ảnh nổi nhẹ mà không lấn nút Google.\n\n## Khi lời nhắn không nói đủ (mặc định của mình)\n\n- **Màu ánh sáng theo thương hiệu của quán**, không theo ảnh mẫu: ảnh mẫu cho khung và *cảm giác* (mạnh, sang, ấm), quán cho màu.\n  Mẫu xe RIMBERIO dùng cam đỏ cho cảm giác mạnh; quán 21 Detailing logo xanh → đèn xanh, giữ độ tương phản cao và đèn đỏ có sẵn trong\n  ảnh (đèn hậu) làm điểm nhấn. Cam đỏ là một lựa chọn trong \"Chọn nhanh\", không tự áp.\n- Tên quán dạng chữ: thay logo ảnh \"phèn\" bằng **chữ mảnh, giãn rộng** (Montserrat 200, giãn ~34) + một nét vẽ nhỏ phía trên.\n- **Khúc B có nội dung thì khúc A phải mời xuống**: dòng \"Các dịch vụ của chúng tôi\", ô \"Bảng giá\", mũi tên nhảy nhẹ, và gợi ý\n  \"Kéo xuống để khám phá thêm\" (`fx.hint`). Bảng giá: thẻ 2 cột, đầu thẻ chữ đậm nghiêng, giá căn phải, viền màu thương hiệu,\n  ghi \"giá tham khảo\".\n- **Safari và Chrome** khác chiều cao màn hình đầu (Safari iPhone có thanh địa chỉ ở dưới, Chrome có hai thanh): giữ mọi thứ quan\n  trọng trên vạch 560 đơn vị, khúc đầu tự dài theo màn hình, không đặt gì sát đáy khúc A.\n- Ô **Ghi chú** ở Bàn dựng có \"Chọn nhanh\" (`lib/canvas/prompt-choices.json`): mức sát mẫu, màu và mức ánh sáng, cầu vồng, nền,\n  vật chính, chữ, nút, icon, hiệu ứng, khúc B, giọng chữ. Học thêm điều gì hay hỏi thì thêm vào đó.\n\n## Chữ premium (21 Detailing, 07/10)\n\n- Tên quán sang: `geo` (Josefin Sans) mảnh 300, **giãn rộng tới gần sát hai mép**; dòng phụ phía trên khác hẳn kiểu chữ — `elegant`\n  (Cormorant) mảnh, giãn rộng, **không đậm** (vd \"PREMIUM CARE\"). Hai dòng không bao giờ cùng một font.\n- Nút Google trên nền tối: `shadow: \"halo\"` (phát sáng trắng) thay vì làm nổi vật chính.\n- Nút phụ phải \"nghiêng ngả, sắc nét\": `tag` nghiêng có con trỏ, TikTok `glitch` (hai mép lệch xanh/đỏ), Zalo `card` gần vuông với\n  icon `zalo-oa`. Bảng giá dạng **vé** (`ve`, uiverse zeeshan_2112) — một cột, số thứ tự, tên dịch vụ chữ chuyển màu, giá bên cuống vé.\n- Logo phụ dáng xe trong kho (`xe-*`, `canh-cua`, `ngua-hi`), không vẽ lại mỗi lần.\n\n## Nút của quán và tệp của quán (07/10)\n\n- **Nút mạng xã hội luôn sinh từ thông tin quán** (`t: \"links\"`): điền bao nhiêu link thì hiện bấy nhiêu nút, chưa điền thì không có,\n  không có link nào thì cả cụm ẩn. Không vẽ tay từng nút mạng xã hội nữa. Kiểu: `icons` (hàng dấu), `pills`, `rows`; `style` mau/net/dac.\n- Bàn dựng có ô thả theo vai: Poster · Nền · Logo · Logo phụ · Ảnh quán · Ảnh phụ (lật) · Font chính · Font đặc biệt · Âm thanh nền.\n  Đặt tệp theo đúng vai: poster/video lên đầu trang, ảnh phụ vào khung lật, font đặc biệt cho tên/tiêu đề (`rieng-dac-biet`), font chính\n  cho chữ thường (`rieng-chinh`, không có thì tự chọn), âm thanh thành nút loa (mặc định tắt).\n- Logo trên nền trắng: tách nền bằng cách xoá phần nền **nối với mép ảnh** (giữ chữ trắng bên trong); ảnh PNG trong suốt thì **không**\n  đặt `shadow` (bóng sẽ thành hình chữ nhật).\n- Mây: `may-troi` (ba lớp trôi, màu từ các điểm của gradient); bầu trời đêm: `sao-troi`.\n\n## Icon\n\n- Mỗi dấu thương hiệu có biến thể (`/gov/kho`): màu thật · nét `-net` (theo màu chữ, hợp trang tối giản) · đặc · tròn/vuông. Chọn\n  theo chất trang; nút Google chọn dấu bằng `mark`. Ghim `maps-giay` (mảnh ghép) chỉ cho kiểu giấy/collage; mặc định dùng `maps` sạch.\n- **Link website luôn gạch chân** (nền tảng tự làm, ở mọi kiểu nút và chữ có `slot: \"website\"`).\n\n## Tâm lý khách theo ngành\n\n- Mỗi ngành trong `lib/canvas/loi-moi.json` có `moment` (khách chạm thẻ lúc nào) và, khi đã dựng quán thật, `tamLy` + `trinhBay`\n  (khách đang nghĩ gì, trang nên nói gì). Đọc trước khi viết chữ phụ. Ví dụ cà phê: khách vừa gọi món, đang **chờ nước** — đừng\n  \"cảm ơn đã ghé\"; chào đúng lúc chờ, rủ **tạo dáng chụp ở góc đẹp hôm nay**, lời mời viết cảm nhận nhẹ cho lúc đã uống.\n\n## Trang không được trống trải\n\n- Chỗ trống thì lấp bằng: icon/sticker trong kho, lớp bột phấn, ảnh poster hoặc ảnh quán (khung polaroid nghiêng), ánh sáng, hoạ tiết phụ.\n- **Dòng pháp lý to hơn** (cỡ 12–13) và **xuống dòng** cho cân, như một phần của thiết kế.\n- **Quanh nút Google có câu mời hợp ngành** (`lib/canvas/loi-moi.json`, 20 ngành + dùng chung): câu \"trên:\" phía trên nút, câu nhẹ phía\n  dưới. Luôn trung lập: không hỏi hài lòng trước, không nhắc sao, không gợi nội dung, không ép \"ngay\" — test `tests/contracts/loi-moi.spec.ts`\n  kiểm mọi câu.\n\n## Khung và màu (bộ 6 mẫu, 06/10)\n\n- **Lấy khung, không lấy màu.** Ảnh mẫu Tài gửi cho biết bố cục, nhịp, kiểu chi tiết; màu luôn lấy từ **ảnh tham chiếu của quán**\n  (mặt tiền, biển hiệu, logo): rút 6–8 màu chủ đạo, chọn một màu nền, một màu thẻ, **một màu nhấn** (ở Bamos: xanh của logo) cho\n  thẻ ló, chữ viết tay, tim, dấu cộng.\n- **Phần khung chung của cả 6 mẫu:** chọn ngôn ngữ góc trên phải; logo tròn + tên quán in đậm; một câu mời/cảm ơn nhỏ; nút Google\n  trắng, chữ G, mũi tên bên phải; các mạng xã hội cùng một kiểu (dòng có mũi tên hoặc ô vuông có icon); pháp lý gạch chân ngay dưới;\n  ô nhắn riêng ở đáy (ở mình là máy bay giấy + lời mời).\n- **Chi tiết tạo \"hồn\":** chữ viết tay nghiêng (tiếng Anh ngắn, 3–4 dòng) cạnh khung chính, tim/dấu cộng lấp lánh rải thưa, một quầng\n  sáng mờ góc trên và góc dưới đối nhau, bóng đổ sâu dưới thẻ.\n- **Logo quán:** có ảnh biển hiệu mà mờ thì vẽ lại logo bằng vector (chữ + biểu tượng), đặt trong vòng tròn sáng có viền tối.\n\n## Đã học từ các lần sửa\n\n| Ngày | Tài nói | Luật |\n|---|---|---|\n| 06/10 | Nút Google \"chưa nổi bóng để nổi bật khỏi nền\" | Nút Google luôn có bóng, mặc định `lift`; núm \"Bóng nút Google\" ở Bàn dựng |\n| 06/10 | \"Mặc định không đưa thêm gì ngoài mẫu screenshot\" | Luật 2 ở trên; @tên chỉ có dấu @ khi ảnh có |\n| 06/10 | Pháp lý \"đừng bỏ ngoài rìa\" | Dòng pháp lý trong khúc A, nền nối mờ |\n| 06/10 | Viền thẻ mờ \"gradient một chút, sinh động hơn\" | Viền gradient cho thẻ kính |\n| 06/10 | \"Hiệu ứng luôn phải có khi vuốt lên xuống\" | Mọi phần tử có hiệu ứng vào, chạy lại khi vuốt |\n| 06/10 | Bóng đổ chưa \"premium\", chữ vẽ tay chưa đầy đặn | Mục \"Chất premium\"; luật 5 |\n| 07/10 | \"Học cách và lưu lại các chi tiết nhỏ\"; nền \"crayon, khói mờ\" của Sentry | Kho chi tiết + cọ bột phấn (mục Chất premium) |\n| 07/10 | Bột phấn \"giống dựng bằng code\"; lưu thông số chứ không lưu màu | Cọ vẽ vảy hạt bằng canvas, chỉ lưu thông số cọ |\n| 07/10 | Ánh cam + cầu vồng kiểu 4RAU; chấm chấm là hoạ tiết ghép, cầu vồng phải mảnh sắc, mờ được | Mục \"Ánh sáng\" |\n| 07/10 | Trang trống thì phải lấp; pháp lý to, xuống dòng; câu mời theo bối cảnh quán | Mục \"Trang không được trống trải\" |\n";
